css:
.belongsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2240;
    background: linear-gradient(160deg, #eef1fb 0%, #e7ecfa 45%, #f4eefb 100%);
    border-radius: 18px;
}

.belongsim-container * {
    box-sizing: border-box;
}

.belongsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #2c2f7a 0%, #4338a6 50%, #7b4fc4 100%);
    color: #f4f3ff;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 32px rgba(44, 47, 122, 0.32);
}

.belongsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.belongsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #d9d2ff;
    background: rgba(255, 255, 255, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.belongsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7e3ff;
}

.belongsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #383d77;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.belongsim-period-counter #currentDay,
.belongsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2c2f7a;
}

.belongsim-round-name {
    background: #ddd7fb;
    color: #3a2f8c;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.belongsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3367;
    background: #fbe3ef;
    padding: 4px 12px;
    border-radius: 999px;
}

.belongsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.belongsim-status-card {
    background: rgba(255, 255, 255, 0.82);
    backdrop-filter: blur(6px);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid rgba(124, 79, 196, 0.16);
    box-shadow: 0 6px 18px rgba(44, 47, 122, 0.08);
    border-top: 4px solid #7b4fc4;
}

.belongsim-card-belonging { border-top-color: #d97706; }
.belongsim-card-safety { border-top-color: #2563c4; }
.belongsim-card-engagement { border-top-color: #0f9d76; }
.belongsim-card-attrition { border-top-color: #c0392b; }

.belongsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a6f9a;
}

.belongsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #2c2f7a;
}

.belongsim-card-belonging .belongsim-value { color: #d97706; }
.belongsim-card-safety .belongsim-value { color: #2563c4; }
.belongsim-card-engagement .belongsim-value { color: #0f9d76; }
.belongsim-card-attrition .belongsim-value { color: #c0392b; }

.belongsim-sublabel {
    font-size: 0.76rem;
    color: #7a7fa6;
    line-height: 1.35;
}

.belongsim-belonging-target .belongsim-value { color: #0f9d76; }
.belongsim-belonging-fail .belongsim-value { color: #d97706; }
.belongsim-attrition-safe .belongsim-value { color: #0f9d76; }
.belongsim-attrition-danger .belongsim-value { color: #c0392b; }

.belongsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2c2f7a;
    color: #eceaff;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.belongsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.belongsim-budget-over #budgetDisplay {
    color: #ffb4a8;
}

.belongsim-briefing {
    display: flex;
    gap: 14px;
    background: rgba(255, 255, 255, 0.88);
    border-left: 5px solid #7b4fc4;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(44, 47, 122, 0.06);
}

.belongsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.belongsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #2c2f7a;
    margin-bottom: 6px;
}

.belongsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #353a63;
}

.belongsim-briefing-text strong { color: #0f9d76; }
.belongsim-briefing-text em { color: #9a3367; font-style: italic; }

.belongsim-controls {
    background: rgba(255, 255, 255, 0.92);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid rgba(124, 79, 196, 0.16);
    box-shadow: 0 6px 18px rgba(44, 47, 122, 0.08);
}

.belongsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2c2f7a;
    border-bottom: 2px solid #e7e3fb;
    padding-bottom: 8px;
}

.belongsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c3060;
    margin: 14px 0 6px;
}

.belongsim-container select,
.belongsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c6c2ec;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f6f4fd;
    color: #1d2240;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.belongsim-container select:focus,
.belongsim-container input[type="number"]:focus {
    outline: none;
    border-color: #7b4fc4;
    box-shadow: 0 0 0 3px rgba(123, 79, 196, 0.16);
}

.belongsim-container select option {
    background-color: #ffffff;
    color: #1d2240;
}

.belongsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #7b4fc4;
}

.belongsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4338a6;
    margin-top: 4px;
}

.belongsim-range-readout span:last-child {
    color: #0f9d76;
    font-weight: 800;
}

.belongsim-hint {
    font-size: 0.8rem;
    color: #7a7fa6;
    margin-top: 4px;
    line-height: 1.4;
}

.belongsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.belongsim-container .btn-primary {
    background: linear-gradient(135deg, #4338a6 0%, #7b4fc4 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(67, 56, 166, 0.30);
}

.belongsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.belongsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c6c2ec;
    color: #6a6f9a;
}

.belongsim-coach {
    background: linear-gradient(135deg, #23264f 0%, #312a6e 100%);
    color: #ece9ff;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(35, 38, 79, 0.28);
}

.belongsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #b9a8f0;
    margin-bottom: 8px;
}

.belongsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.belongsim-coach-body strong { color: #ffd98a; }
.belongsim-coach-body em { color: #ffb4d4; font-style: italic; }

.belongsim-history,
.belongsim-chart {
    background: rgba(255, 255, 255, 0.92);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid rgba(124, 79, 196, 0.16);
    box-shadow: 0 6px 18px rgba(44, 47, 122, 0.08);
}

.belongsim-history h3,
.belongsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2c2f7a;
}

.belongsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c3060;
}

.belongsim-container table#usfHistoryTable th {
    background: #eceafb;
    color: #2c2f7a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd7fb;
}

.belongsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0eefa;
}

.belongsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8f6fd;
}

.belongsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .belongsim-container {
        padding: 14px;
    }
    .belongsim-header h1 {
        font-size: 1.7rem;
    }
    .belongsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .belongsim-value {
        font-size: 2rem;
    }
    .belongsim-clock {
        margin-left: 0;
    }
    .belongsim-period-counter {
        font-size: 0.88rem;
    }
    .belongsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .belongsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion message (formatCompletionMessage) */
.belongsim-completion { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #2c2f7a; }
.belongsim-cm-head { display: flex; align-items: center; gap: 18px; flex-wrap: wrap; padding-bottom: 14px; border-bottom: 1px solid rgba(44,47,122,0.14); margin-bottom: 16px; }
.belongsim-cm-score { font-size: 46px; font-weight: 800; line-height: 1; color: #0f9d76; }
.belongsim-cm-score-max { font-size: 18px; font-weight: 600; color: #4338a6; margin-left: 2px; }
.belongsim-cm-grade { font-size: 18px; font-weight: 700; color: #2c2f7a; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.belongsim-cm-badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: .02em; padding: 3px 10px; border-radius: 999px; }
.belongsim-cm-yes { background: rgba(15,157,118,0.15); color: #0b7a5b; }
.belongsim-cm-no { background: rgba(192,57,43,0.12); color: #b03325; }
.belongsim-cm-warn { background: rgba(217,119,6,0.16); color: #a65a06; }
.belongsim-cm-metrics { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 18px; }
.belongsim-cm-metric { flex: 1 1 110px; background: #f2f1fb; border: 1px solid rgba(44,47,122,0.10); border-radius: 10px; padding: 12px 14px; text-align: center; }
.belongsim-cm-mv { display: block; font-size: 24px; font-weight: 800; color: #2c2f7a; }
.belongsim-cm-ml { display: block; font-size: 12px; font-weight: 600; color: #4338a6; margin-top: 2px; }
.belongsim-cm-insights-title { font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: .04em; color: #4338a6; margin-bottom: 8px; }
.belongsim-cm-insights { margin: 0; padding-left: 20px; }
.belongsim-cm-insights li { font-size: 14px; line-height: 1.5; color: #33385a; margin-bottom: 8px; }

