(function() {
    'use strict';

    class BelongingAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Building Belonging`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.START_BELONGING = 2.6;    // newer / under-represented members, out of 5
            this.TARGET_BELONGING = 3.5;   // quarter-end target for at-risk segment
            this.CORE_BELONGING = 4.2;     // long-tenured core (ceiling reference)
            this.START_SAFETY = 41;        // newer members, 0-100 (company avg 72)
            this.START_ENGAGEMENT = 61;    // squad, 0-100 (was 76)
            this.START_ATTRITION = 22;     // regretted attrition %, target <= 12 (core 5)
            this.TARGET_ATTRITION = 12;    // quarter-end threshold
            this.BUDGET_CAP = 40;          // effort/time budget, GBP k for the cycle
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    belonging: this.START_BELONGING,
                    safety: this.START_SAFETY,
                    engagement: this.START_ENGAGEMENT,
                    attrition: this.START_ATTRITION,
                    budgetUsed: 0,
                    tokenism: false,
                    incidentResolved: false,
                    belongingHistory: [this.START_BELONGING],
                    safetyHistory: [this.START_SAFETY],
                    engagementHistory: [this.START_ENGAGEMENT],
                    attritionHistory: [this.START_ATTRITION],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    read: `disaggregate`,
                    distinguish: `both`,
                    mechanisms: `three`,
                    rigour: 60,
                    headline: `airtime`,
                    channel: `transparent`,
                    structures: `buddy`,
                    invest: 14,
                    model: 60,
                    incident: `repair`,
                    senior: `coach`,
                    pressure: `infra`,
                    indicators: `leading`,
                    embed: `system`,
                    pitch: `evidence`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const rd = document.getElementById(`readInput`);
                const di = document.getElementById(`distinguishInput`);
                const me = document.getElementById(`mechanismsInput`);
                const rg = document.getElementById(`rigourInput`);
                if (rd) decisions.read = rd.value;
                if (di) decisions.distinguish = di.value;
                if (me) decisions.mechanisms = me.value;
                if (rg) decisions.rigour = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const hd = document.getElementById(`headlineInput`);
                const ch = document.getElementById(`channelInput`);
                const st = document.getElementById(`structuresInput`);
                const iv = document.getElementById(`investInput`);
                if (hd) decisions.headline = hd.value;
                if (ch) decisions.channel = ch.value;
                if (st) decisions.structures = st.value;
                if (iv) decisions.invest = parseFloat(iv.value);
                if (!Number.isFinite(decisions.invest) || decisions.invest < 0) {
                    warn(`warn_invest_negative`); return false;
                }
                if (decisions.invest > this.BUDGET_CAP) {
                    warn(`warn_invest_cap`); return false;
                }
            } else if (round === 3) {
                const md = document.getElementById(`modelInput`);
                const inc = document.getElementById(`incidentInput`);
                const sn = document.getElementById(`seniorInput`);
                const pr = document.getElementById(`pressureInput`);
                if (md) decisions.model = parseInt(md.value, 10);
                if (inc) decisions.incident = inc.value;
                if (sn) decisions.senior = sn.value;
                if (pr) decisions.pressure = pr.value;
                if (!Number.isFinite(decisions.model) || decisions.model < 0 || decisions.model > 100) {
                    warn(`warn_model_range`); return false;
                }
            } else if (round === 4) {
                const ind = document.getElementById(`indicatorsInput`);
                const em = document.getElementById(`embedInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ind) decisions.indicators = ind.value;
                if (em) decisions.embed = em.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: belonging (/5, small), safety & engagement (0-100), attrition (% — NEGATIVE delta = improvement).
            let belongingDelta = 0, safetyDelta = 0, engagementDelta = 0, attritionDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: read past the average (Common Error 1 — trusting the average).
                if (d.read === `disaggregate`) {
                    belongingDelta += 0.15; safetyDelta += 4; coachKey = `coach_r1_disaggregate`;
                } else if (d.read === `headline`) {
                    belongingDelta -= 0.10; safetyDelta -= 4; attritionDelta += 2; coachKey = `coach_r1_headline`;
                } else {
                    belongingDelta -= 0.06; safetyDelta -= 2; coachKey = `coach_r1_onequote`;
                }

                // Distinguish belonging from psychological safety (Key Concept).
                if (d.distinguish === `both`) {
                    belongingDelta += 0.12; safetyDelta += 3;
                } else if (d.distinguish === `safetyonly`) {
                    belongingDelta -= 0.08; safetyDelta += 1; coachKey = `coach_r1_safetyonly`;
                } else {
                    safetyDelta += 1; coachKey = (coachKey === `coach_r1_disaggregate`) ? `coach_r1_same` : coachKey;
                }

                // Name the three exclusionary mechanisms (the diagnosis deliverable).
                if (d.mechanisms === `three`) {
                    belongingDelta += 0.12; safetyDelta += 3; engagementDelta += 3;
                    if (d.read === `disaggregate` && d.distinguish === `both`) coachKey = `coach_r1_sharp`;
                } else if (d.mechanisms === `people`) {
                    belongingDelta -= 0.08; safetyDelta -= 4; coachKey = `coach_r1_people`;
                } else {
                    belongingDelta -= 0.10; safetyDelta -= 3; coachKey = `coach_r1_event`;
                }

                // Rigour: willingness to act on the 2.6, not the 3.4.
                if (d.rigour >= 60) { belongingDelta += 0.08; safetyDelta += 2; }
                else if (d.rigour <= 25) { belongingDelta -= 0.08; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.read === `disaggregate` && d.distinguish === `both` && d.mechanisms === `three`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose inclusion interventions; avoid tokenism (Common Error 2).
                switch (d.headline) {
                    case `airtime`:
                        belongingDelta += 0.22; safetyDelta += 7; engagementDelta += 6; attritionDelta -= 2;
                        coachKey = `coach_r2_airtime`; break;
                    case `celebration`:
                        // Performative inclusion singles people out and deepens othering.
                        belongingDelta -= 0.18; safetyDelta -= 6; engagementDelta -= 2; attritionDelta += 3;
                        ds.tokenism = true; coachKey = `coach_r2_celebration`; break;
                    case `email`:
                        belongingDelta -= 0.04; engagementDelta -= 1; coachKey = `coach_r2_email`; break;
                }

                // The after-work channel where decisions migrate.
                switch (d.channel) {
                    case `transparent`: belongingDelta += 0.14; safetyDelta += 4; engagementDelta += 3; break;
                    case `ignore`: belongingDelta -= 0.10; safetyDelta -= 4; coachKey = (coachKey === `coach_r2_airtime`) ? `coach_r2_channelmiss` : coachKey; break;
                    case `ban`: belongingDelta -= 0.04; engagementDelta -= 4; coachKey = `coach_r2_ban`; break;
                }

                // Lasting structures for newer members.
                switch (d.structures) {
                    case `buddy`: belongingDelta += 0.16; safetyDelta += 3; engagementDelta += 4; attritionDelta -= 2; break;
                    case `token`: belongingDelta -= 0.12; safetyDelta -= 3; ds.tokenism = true; coachKey = `coach_r2_token`; break;
                    case `none`: belongingDelta -= 0.04; coachKey = (coachKey === `coach_default`) ? `coach_r2_nostruct` : coachKey; break;
                }

                // Effort investment — structural work costs effort; underspending limits the gains.
                spend += d.invest;
                if (d.invest >= 12) { belongingDelta += 0.06; safetyDelta += 2; }
                else if (d.invest <= 3) { belongingDelta -= 0.06; coachKey = `coach_r2_noinvest`; }

                summaryKey = (d.headline === `airtime` && d.channel === `transparent` && d.structures === `buddy`) ? `sum_r2_good`
                    : ((d.headline === `celebration` || d.structures === `token`) ? `sum_r2_token` : `sum_r2_weak`);
            } else if (round === 3) {
                // Model safety + resolve the live incident (Common Errors 3, 4, 5 + delivery pressure).

                // The leader's own micro-behaviours (Common Error 5 — delegating belonging).
                if (d.model >= 70) { belongingDelta += 0.20; safetyDelta += 7; engagementDelta += 5; }
                else if (d.model >= 45) { belongingDelta += 0.10; safetyDelta += 4; }
                else { belongingDelta -= 0.10; safetyDelta -= 6; coachKey = `coach_r3_nomodel`; }

                // The exclusion incident — the loudest signal the leader sends (Common Error 3).
                switch (d.incident) {
                    case `repair`:
                        belongingDelta += 0.22; safetyDelta += 6; engagementDelta += 4; attritionDelta -= 4;
                        ds.incidentResolved = true; coachKey = `coach_r3_repair`; break;
                    case `smooth`:
                        belongingDelta -= 0.14; safetyDelta -= 6; attritionDelta += 3; coachKey = `coach_r3_smooth`; break;
                    case `ignore`:
                        belongingDelta -= 0.22; safetyDelta -= 10; engagementDelta -= 4; attritionDelta += 5; coachKey = `coach_r3_ignore`; break;
                }

                // Engaging the senior engineer (Common Error 4 — public confrontation).
                switch (d.senior) {
                    case `coach`: belongingDelta += 0.14; safetyDelta += 5; coachKey = (d.incident === `repair`) ? `coach_r3_coach` : coachKey; break;
                    case `public`: safetyDelta -= 12; engagementDelta -= 3; attritionDelta += 2; coachKey = `coach_r3_public`; break;
                    case `avoid`: belongingDelta -= 0.10; safetyDelta -= 5; coachKey = `coach_r3_avoid`; break;
                }

                // The delivery-pressure objection.
                switch (d.pressure) {
                    case `infra`: belongingDelta += 0.10; safetyDelta += 3; engagementDelta += 5; attritionDelta -= 3; break;
                    case `park`: belongingDelta -= 0.16; safetyDelta -= 6; engagementDelta -= 4; attritionDelta += 4; coachKey = `coach_r3_park`; break;
                    case `either`: belongingDelta -= 0.04; engagementDelta -= 1; coachKey = (coachKey === `coach_default`) ? `coach_r3_either` : coachKey; break;
                }

                summaryKey = (d.model >= 70 && d.incident === `repair` && d.senior === `coach` && d.pressure === `infra`) ? `sum_r3_good`
                    : ((d.senior === `public` || d.incident === `ignore`) ? `sum_r3_harm` : `sum_r3_weak`);
            } else if (round === 4) {
                // Sustain belonging as a property of the system (Common Error 5 + decay).
                switch (d.indicators) {
                    case `leading`: belongingDelta += 0.14; safetyDelta += 4; engagementDelta += 4; attritionDelta -= 3; coachKey = `coach_r4_leading`; break;
                    case `lagging`: safetyDelta += 1; coachKey = `coach_r4_lagging`; break;
                    case `none`: belongingDelta -= 0.10; safetyDelta -= 5; attritionDelta += 3; coachKey = `coach_r4_nomeasure`; break;
                }

                // Embed the norms into the system vs a one-off campaign.
                switch (d.embed) {
                    case `system`: belongingDelta += 0.18; safetyDelta += 5; engagementDelta += 4; attritionDelta -= 3; break;
                    case `campaign`: belongingDelta -= 0.10; safetyDelta -= 5; coachKey = `coach_r4_campaign`; break;
                    case `leaderonly`: belongingDelta -= 0.06; safetyDelta -= 3; coachKey = `coach_r4_leaderonly`; break;
                }

                // The 3-minute pitch.
                switch (d.pitch) {
                    case `evidence`: belongingDelta += 0.10; safetyDelta += 3; engagementDelta += 3; coachKey = (d.embed === `system`) ? `coach_r4_evidence` : coachKey; break;
                    case `optics`: belongingDelta -= 0.06; safetyDelta -= 3; coachKey = `coach_r4_optics`; break;
                    case `defensive`: safetyDelta -= 4; engagementDelta -= 2; coachKey = `coach_r4_defensive`; break;
                }

                // Conviction nudges belonging and engagement.
                belongingDelta += (d.conviction - 60) / 600;
                engagementDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.indicators === `leading` && d.embed === `system` && d.pitch === `evidence`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.min(this.BUDGET_CAP, Math.round((ds.budgetUsed + spend) * 100) / 100);

            // Apply deltas with bounds. Belonging caps a touch above the core; the others on 0-100.
            ds.belonging = Math.max(0, Math.min(5, Math.round((ds.belonging + belongingDelta) * 100) / 100));
            ds.safety = Math.max(0, Math.min(100, Math.round(ds.safety + safetyDelta)));
            ds.engagement = Math.max(0, Math.min(100, Math.round(ds.engagement + engagementDelta)));
            // Attrition risk: lower is better. Floor at the core's 5%, cap at 35%.
            ds.attrition = Math.max(5, Math.min(35, Math.round((ds.attrition + attritionDelta) * 10) / 10));

            ds.belongingHistory.push(ds.belonging);
            ds.safetyHistory.push(ds.safety);
            ds.engagementHistory.push(ds.engagement);
            ds.attritionHistory.push(ds.attrition);

            // v1.1.0: publish composite (0-100) to the reporting/grading layer every period.
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                belonging: ds.belonging,
                belongingDelta: Math.round(belongingDelta * 100) / 100,
                safety: ds.safety,
                safetyDelta: Math.round(safetyDelta),
                engagement: ds.engagement,
                engagementDelta: Math.round(engagementDelta),
                attrition: ds.attrition,
                attritionDelta: Math.round(attritionDelta * 10) / 10,
                budgetUsed: ds.budgetUsed,
                tokenism: ds.tokenism,
                incidentResolved: ds.incidentResolved,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

