        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.belongingHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                belongChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.belongingHistory.map((v) => Math.round(v * 20)) },
