        // Shared composite (0-100). Written to domainState.performance.overallScore each period
        // for the reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            var belonging = Math.round(ds.belonging * 10) / 10;
            var safety = Math.round(ds.safety);
            var engagement = Math.round(ds.engagement);
            var attrition = Math.round(ds.attrition * 10) / 10;
            var belongScore = Math.min(100, (belonging / 5) * 100);
            var attritionScore = Math.max(0, 100 - (attrition - 5) * (100 / 30));
            return Math.round(belongScore * 0.34 + safety * 0.30 + engagement * 0.18 + attritionScore * 0.18);
        }

        _cl(key, fallback) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    var v = window.mySimulation.t(key);
                    if (v && v !== key) return v;
                }
            } catch (e) {}
            return fallback;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const belonging = Math.round(ds.belonging * 10) / 10;
            const safety = Math.round(ds.safety);
            const engagement = Math.round(ds.engagement);
            const attrition = Math.round(ds.attrition * 10) / 10;

            const hitBelonging = belonging >= this.TARGET_BELONGING;
            const safeAttrition = attrition <= this.TARGET_ATTRITION;
            const escalationAvoided = hitBelonging && safeAttrition;
            const realInclusion = escalationAvoided && safety >= 60 && !ds.tokenism && ds.incidentResolved;

            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            let performanceKey = `grade_closed`;
            if (realInclusion && composite >= 74) performanceKey = `grade_built`;
            else if (realInclusion) performanceKey = `grade_avoided`;
            else if (escalationAvoided) performanceKey = `grade_fragile`;
            else if (hitBelonging || safeAttrition) performanceKey = `grade_partial`;
            else if (belonging > this.START_BELONGING + 0.4) performanceKey = `grade_improving`;
            const performance = T(performanceKey);

            const insights = [];
            if (realInclusion) insights.push(window.mySimulation.t(`insight_built`));
            else if (escalationAvoided && ds.tokenism) insights.push(window.mySimulation.t(`insight_tokenism`));
            else if (escalationAvoided) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!ds.incidentResolved) insights.push(window.mySimulation.t(`insight_incident`));
            if (!safeAttrition) insights.push(window.mySimulation.t(`insight_attrition`));
            if (safety < 55) insights.push(window.mySimulation.t(`insight_safety`));
            if (realInclusion && belonging >= 3.9) insights.push(window.mySimulation.t(`insight_benchmark`));

            return {
                belonging: belonging,
                safety: safety,
                engagement: engagement,
                attrition: attrition,
                hitBelonging: hitBelonging,
                safeAttrition: safeAttrition,
                escalationAvoided: escalationAvoided,
                tokenism: ds.tokenism,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.overallScore === 'number') ? s.overallScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var met = !!s.escalationAvoided;
            var badge = met
                ? '<span class="belongsim-cm-badge belongsim-cm-yes">' + T('cm_met') + '</span>'
                : '<span class="belongsim-cm-badge belongsim-cm-no">' + T('cm_missed') + '</span>';
            var tokBadge = s.tokenism
                ? '<span class="belongsim-cm-badge belongsim-cm-warn">' + T('cm_tokenism_badge') + '</span>'
                : '';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="belongsim-cm-metric"><span class="belongsim-cm-mv">' + Number(s.belonging || 0).toFixed(1) + '</span><span class="belongsim-cm-ml">' + T('cm_m_belonging') + '</span></div>'
                + '<div class="belongsim-cm-metric"><span class="belongsim-cm-mv">' + Math.round(s.safety || 0) + '</span><span class="belongsim-cm-ml">' + T('cm_m_safety') + '</span></div>'
                + '<div class="belongsim-cm-metric"><span class="belongsim-cm-mv">' + Math.round(s.engagement || 0) + '</span><span class="belongsim-cm-ml">' + T('cm_m_engagement') + '</span></div>'
                + '<div class="belongsim-cm-metric"><span class="belongsim-cm-mv">' + (Math.round((s.attrition || 0) * 10) / 10) + '%</span><span class="belongsim-cm-ml">' + T('cm_m_attrition') + '</span></div>';
            return ''
                + '<div class="belongsim-completion">'
                +   '<div class="belongsim-cm-head">'
                +     '<div class="belongsim-cm-score">' + score + '<span class="belongsim-cm-score-max">/100</span></div>'
                +     '<div class="belongsim-cm-grade">' + grade + ' ' + badge + tokBadge + '</div>'
                +   '</div>'
                +   '<div class="belongsim-cm-metrics">' + metrics + '</div>'
                +   '<div class="belongsim-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="belongsim-cm-insights">' + items + '</ul>'
                + '</div>';
        }

